#!/bin/sh
# 板端直连 Agnes API 测试
curl -k -s -m 25 -o /data/chat_resp.txt \
  https://apihub.agnes-ai.com/v1/chat/completions \
  -H "Authorization: Bearer sk-<REDACTED>" \
  -H "Content-Type: application/json" \
  -d @/data/chat_test.json
echo "EXIT=$?"
#!/bin/bash
grep -oE 'strcmp\(cmd, "[a-zA-Z_]+"\)' /root/openvela/packages/ai_agent/src/channels/nsh_commands.c \
  | sed -E 's/strcmp\(cmd, "([a-zA-Z_]+)"\)/\1/' \
  | sort -u

