  { "MIC2 gain volume", 31 },

  /* ADC 数字增益：本实验标定的关键项。
   * 厂商默认 160 比可用点低约 20 dB，而 160~255 之间只有约 36 dB 的
   * 可调范围、工作窗口不宽，所以取实测"体检可用"的 205。 */
  { "ADC1 digital volume", 205 },
  { "ADC2 digital volume", 205 },
};

#define MIC_ROUTE_GAIN_COUNT (sizeof(g_mic_gains) / sizeof(g_mic_gains[0]))

int mic_route_query(const char *name, unsigned long *value)
{
  snd_ctl_info_t info;

  if (name == NULL || value == NULL)
    {
      return -EINVAL;
    }

  if (snd_ctl_get(MIC_ROUTE_CARD, name, &info) != 0)
    {
      return -ENOENT;
    }

  *value = info.value;
  return OK;
}

int mic_route_apply_gain(void)
{
  size_t i;
  unsigned int failures = 0;

  for (i = 0; i < MIC_ROUTE_GAIN_COUNT; i++)
  {
    const struct mic_route_gain *gain = &g_mic_gains[i];
    snd_ctl_info_t               info;

    if (snd_ctl_get(MIC_ROUTE_CARD, gain->name, &info) != 0)
      {
        syslog(LOG_ERR, "[%s] gain control '%s' not found on card '%s'\n",
               TAG, gain->name, MIC_ROUTE_CARD);
        failures++;
        continue;
      }

    /* --- 只升不降：已经不低于目标值就保持不动 ----------------------- */

    if (info.value >= gain->target)
      {
        syslog(LOG_INFO, "[%s] '%s' already at %lu (>= %lu), left as is\n",
               TAG, gain->name, info.value, gain->target);
        continue;
      }

    if (snd_ctl_set(MIC_ROUTE_CARD, gain->name, (unsigned int)gain->target) != 0)
      {
        syslog(LOG_ERR, "[%s] failed to raise '%s' from %lu to %lu\n",
               TAG, gain->name, info.value, gain->target);
        failures++;
        continue;
      }

    /* --- 回读确认（驱动可能接受调用但不生效） ----------------------- */

    if (snd_ctl_get(MIC_ROUTE_CARD, gain->name, &info) != 0 ||
        info.value < gain->target)
      {
        syslog(LOG_ERR,
               "[%s] '%s' did not take effect (now %lu, want >= %lu)\n",
               TAG, gain->name, info.value, gain->target);
        failures++;
        continue;
      }

    syslog(LOG_INFO, "[%s] '%s' raised to %lu\n",
           TAG, gain->name, info.value);
  }

  if (failures != 0)
    {
      /* 与开关不同，增益失败**不会**让采集直接报错，只会让录到的声音偏轻
       * ——而这种问题很容易被误判成"麦克风不行"或"ASR 不准"，所以这里
       * 必须显式告警。 */
      syslog(LOG_ERR,
             "[%s] %u of %u gain controls failed; capture will work but the "
             "recorded level may be ~20 dB too low, hurting ASR accuracy\n",
             TAG, failures, (unsigned)MIC_ROUTE_GAIN_COUNT);
      return -EIO;
    }

  return OK;
}

int mic_route_enable(void)
{
  size_t i;
  unsigned int failures = 0;

  for (i = 0; i < MIC_ROUTE_COUNT; i++)
  {
    const struct mic_route_ctl *route = &g_mic_routes[i];
    snd_ctl_info_t              info;

    /* --- 查是否存在 ------------------------------------------------- */

    if (snd_ctl_get(MIC_ROUTE_CARD, route->name, &info) != 0)
    {
      /* 名字对不上多半是固件版本差异。把名字打出来，方便直接改表。 */
      syslog(LOG_ERR, "[%s] control '%s' not found on card '%s'\n",
             TAG, route->name, MIC_ROUTE_CARD);
      failures++;
      continue;
    }

    /* --- 已是目标值就跳过（幂等） ----------------------------------- */

    if (info.value == route->on_value)
    {
      syslog(LOG_INFO, "[%s] '%s' already on\n", TAG, route->name);
      continue;
    }

    /* --- 下发 ------------------------------------------------------- */

    if (snd_ctl_set(MIC_ROUTE_CARD, route->name, route->on_value) != 0)
    {
      syslog(LOG_ERR, "[%s] failed to enable '%s' (was %lu)\n",
             TAG, route->name, info.value);
      failures++;
      continue;
    }

    /* --- 回读确认：驱动可能接受调用但不生效 ------------------------- */

    if (snd_ctl_get(MIC_ROUTE_CARD, route->name, &info) != 0 ||
        info.value != route->on_value)
    {
      syslog(LOG_ERR,
             "[%s] '%s' did not take effect (now %lu, want %u)\n",
             TAG, route->name, info.value, route->on_value);
      failures++;
      continue;
    }

    syslog(LOG_INFO, "[%s] '%s' enabled\n", TAG, route->name);
  }

  /* 开关之后紧接着补增益。两者都失败才算采集不可用，所以这里分别判定：
   * 开关失败 -> 采集会直接报错（致命）；增益失败 -> 采集能用但声音偏轻。 */
  if (mic_route_apply_gain() != OK)
    {
      failures++;
    }

  if (failures != 0)
  {
    /* 把后果一并说清楚：这条日志出现之后，采集大概率会报那条误导性错误。 */
    syslog(LOG_ERR,
           "[%s] %u of %u routes failed; capture will likely fail with "
           "'capture only support 1~3 channel'\n",
           TAG, failures, (unsigned)MIC_ROUTE_COUNT);
    return -EIO;
  }

  syslog(LOG_INFO, "[%s] capture route ready\n", TAG);
  return OK;
}

