static int baidu_asr_init_ops(void)
{
  /* 采集输入通路必须先打开，否则打开采集设备时会在 hw_params 阶段失败，
   * 并报一条与真实原因完全不符的 "capture only support 1~3 channel"。
   * 实测板子每次开机后这些开关都是 Off，且不持久化 —— 见 mic_route.c。
   *
   * 失败不致命：可能只是这台设备的控制项名称与 R528 参考板不同。
   * 此时仅告警并继续，让上层拿到真实的采集错误，而不是被这里提前挡掉
   * （否则会掩盖问题、让排查方向跑偏）。
   */
  if (mic_route_enable() != OK)
    {
      syslog(LOG_WARNING,
             "[%s] mic route not ready; capture may fail\n", TAG);
    }

  return baidu_auth_init();
}

static int baidu_asr_recognize_ops(const unsigned char *pcm_data,
                                   size_t               pcm_len,
                                   char                *text_out,
                                   size_t               text_cap)
{
  return baidu_asr_recognize(pcm_data, pcm_len, text_out, text_cap);
}

/* deinit is NULL on purpose: the access_token is shared with the TTS backend
 * (see baidu_auth.c). Tearing it down when only the ASR backend unloads would
 * needlessly invalidate the token for the other backend. Call
 * baidu_auth_deinit() explicitly at shutdown if you want the copies scrubbed.
 */
static const voice_asr_ops_t s_baidu_asr_ops = {
  .name      = "baidu",
