"""配置加载。

优先级：环境变量 > config.yaml > config.example.yaml 的默认值

为什么要环境变量覆盖：密钥写在文件里容易误提交。临时调试或 CI 里可以用
``BAIDU_API_KEY`` / ``BAIDU_SECRET_KEY`` / ``DEEPSEEK_API_KEY`` 注入，
不必落盘。

路径约定：``config.yaml`` 里的相对路径**以 prototype/ 目录为基准**解析，
这样从任何工作目录调用脚本都能找到文件。
"""

from __future__ import annotations

import os
from functools import lru_cache
from pathlib import Path
from typing import Any

import yaml

PROTO_DIR = Path(__file__).resolve().parent
ROOT_DIR = PROTO_DIR.parent

DEFAULT_CONFIG_PATH = PROTO_DIR / "config.yaml"
EXAMPLE_CONFIG_PATH = PROTO_DIR / "config.example.yaml"

# 环境变量覆盖表：配置文件里的点号路径 -> 环境变量名
_ENV_OVERRIDES: dict[str, str] = {
    "baidu.api_key": "BAIDU_API_KEY",
    "baidu.secret_key": "BAIDU_SECRET_KEY",
    "deepseek.api_key": "DEEPSEEK_API_KEY",
}


class ConfigError(RuntimeError):
    """配置缺失或不可用。"""


class Config:
    """薄薄的配置包装，提供点号取值与路径解析。"""

    def __init__(self, raw: dict[str, Any], source: Path) -> None:
        self._raw = raw or {}
        self.source = source

    # -- 取值 ------------------------------------------------------------

    def get(self, dotted: str, default: Any = None) -> Any:
        node: Any = self._raw
        for part in dotted.split("."):
            if not isinstance(node, dict) or part not in node:
                return default
            node = node[part]
        return default if node is None else node

    def require(self, dotted: str) -> Any:
        """取一个必填项，缺失时抛出可读的错误。"""
        value = self.get(dotted)
        if value is None or value == "":
            raise ConfigError(
                f"缺少必填配置项 `{dotted}`。\n"
                f"请复制 {EXAMPLE_CONFIG_PATH.name} 为 config.yaml 并填写，"
                f"或设置对应环境变量。\n"
                f"当前配置来源：{self.source}"
            )
        return value

    def path(self, dotted: str, default: str | None = None) -> Path:
        """取一个路径项，相对路径按 prototype/ 解析为绝对路径。"""
        raw = self.get(dotted, default)
        if raw is None:
            raise ConfigError(f"缺少路径配置项 `{dotted}`")
        p = Path(str(raw))
        return p if p.is_absolute() else (PROTO_DIR / p).resolve()

    # -- 便捷访问 --------------------------------------------------------

    @property
    def baidu_api_key(self) -> str:
        return str(self.require("baidu.api_key"))

    @property
    def baidu_secret_key(self) -> str:
        return str(self.require("baidu.secret_key"))

    @property
    def deepseek_api_key(self) -> str:
        return str(self.require("deepseek.api_key"))

    @property
    def age_band(self) -> str:
        return str(self.get("robot.age_band", "24-36"))

    @property
    def reply_max_chars(self) -> int:
        return int(self.get("robot.reply_max_chars", 30))

    @property
    def audio_spec(self) -> dict[str, int]:
        return {
            "sample_rate": int(self.get("audio.sample_rate", 16000)),
            "bits": int(self.get("audio.bits", 16)),
            "channels": int(self.get("audio.channels", 1)),
        }

    def ensure_output_dir(self) -> Path:
        out = self.path("paths.output_dir", "./out")
        out.mkdir(parents=True, exist_ok=True)
        return out


def _apply_env_overrides(raw: dict[str, Any]) -> None:
    for dotted, env_name in _ENV_OVERRIDES.items():
        value = os.environ.get(env_name)
        if not value:
            continue
        node = raw
        parts = dotted.split(".")
        for part in parts[:-1]:
            node = node.setdefault(part, {})
        node[parts[-1]] = value


@lru_cache(maxsize=4)
def load_config(path: str | Path | None = None) -> Config:
    """加载配置。

    :param path: 指定配置文件；省略时优先 ``config.yaml``，
                 不存在则退回 ``config.example.yaml``（此时密钥是占位符，
                 任何需要密钥的操作都会抛出带指引的 ConfigError）
    """
    if path is not None:
        cfg_path = Path(path)
        if not cfg_path.is_absolute():
            cfg_path = (PROTO_DIR / cfg_path).resolve()
        if not cfg_path.exists():
            raise ConfigError(f"指定的配置文件不存在：{cfg_path}")
    elif DEFAULT_CONFIG_PATH.exists():
        cfg_path = DEFAULT_CONFIG_PATH
    else:
        cfg_path = EXAMPLE_CONFIG_PATH

    raw = yaml.safe_load(cfg_path.read_text(encoding="utf-8")) or {}
    _apply_env_overrides(raw)
    return Config(raw, cfg_path)


def is_placeholder(value: str) -> bool:
    """判断配置值是否还是模板里的占位符。"""
    markers = ("在此填入", "你的", "sk-在此", "<", "填入")
    return any(m in value for m in markers)

