for attempt in range(retries + 1):
    started = time.time()
    try:
        resp = requests.post(
            url,
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            json=payload,
            timeout=timeout,
        )
    except requests.RequestException as exc:
        last_err = f"网络请求失败：{exc}"
        if attempt < retries:
            time.sleep(1.5 * (attempt + 1))
            continue
        return LlmResult(ok=False, err_msg=last_err, elapsed_s=time.time() - started)

    elapsed = time.time() - started

    if resp.status_code != 200:
        detail = resp.text[:300]
        hint = ""
        if resp.status_code == 401:
            hint = "（API Key 无效）"
        elif resp.status_code == 402:
            hint = "（账户余额不足，需要充值）"
        elif resp.status_code == 429:
            hint = "（请求过于频繁，稍后重试）"
        last_err = f"HTTP {resp.status_code}{hint}：{detail}"
        # 401/402 是确定性错误，重试没意义
        if resp.status_code in (400, 401, 402) or attempt >= retries:
            return LlmResult(ok=False, err_msg=last_err, elapsed_s=elapsed)
        time.sleep(1.5 * (attempt + 1))
        continue

    try:
        data = resp.json()
    except ValueError:
        return LlmResult(
            ok=False,
            err_msg=f"返回内容不是 JSON：{resp.text[:200]}",
            elapsed_s=elapsed,
        )

