 * 内部状态
 * ========================================================================== */

struct child_face {
    lv_obj_t *root;
    lv_obj_t *head;
    lv_obj_t *eye_l;
    lv_obj_t *eye_r;
    lv_obj_t *hi_l;        /* 左眼高光 */
    lv_obj_t *hi_r;        /* 右眼高光 */
    lv_obj_t *cheek_l;
    lv_obj_t *cheek_r;
    lv_obj_t *mouth;
    lv_timer_t *timer;
    int      state;
    int      tick;
    int      s;            /* 基准尺寸 = min(W,H) */
    int      inited;
};

static struct child_face g_face;

/* --------------------------------------------------------------------------
 * 状态 -> 视觉参数（纯函数，便于测试）
 * 参数都是相对 s（短边）的比例，乘以 1000 保留精度
 * -------------------------------------------------------------------------- */

struct look {
    int eye_h;       /* 眼睛高度，千分比（× s / 1000） */
    int mouth_w;
    int mouth_h;
    int cheek_opa;   /* 腮红不透明度 0-255 */
};

static void look_for(int state, int tick, struct look *out)
{
    out->cheek_opa = LV_OPA_60;

    switch (state) {
    case CHILD_FACE_LISTENING:
        out->eye_h    = 200;   /* 睁大 */
        out->mouth_w  = 110;
        out->mouth_h  = 55;
        out->cheek_opa = LV_OPA_40;
        break;

    case CHILD_FACE_THINKING:
        out->eye_h    = 160 - ((tick % 20) < 10 ? 40 : 0);
        out->mouth_w  = 95;
        out->mouth_h  = 30;
        out->cheek_opa = LV_OPA_80;
        break;

    case CHILD_FACE_SPEAKING: {
        int phase = tick % 8;
        int swing = (phase < 4) ? phase : (8 - phase);
        out->eye_h   = 170;
        out->mouth_w = 95 + 90 * swing / 4;
        out->mouth_h = 30 + 90 * swing / 4;
        out->cheek_opa = LV_OPA_60;
        break;
    }

    case CHILD_FACE_HAPPY:
        out->eye_h    = 60;    /* 眯眼笑 */
        out->mouth_w  = 185;
        out->mouth_h  = 95;
        out->cheek_opa = LV_OPA_100;
        break;

    case CHILD_FACE_SLEEPY:
        out->eye_h    = 75;
        out->mouth_w  = 80;
        out->mouth_h  = 22;
        out->cheek_opa = LV_OPA_30;

        choices = data.get("choices") or []
        if not choices:
            return LlmResult(
                ok=False, err_msg=f"返回中没有 choices：{data}", elapsed_s=elapsed, raw=data
            )

        text = (choices[0].get("message", {}) or {}).get("content", "") or ""
        usage = data.get("usage", {}) or {}

        warnings: list[str] = []
        finish = choices[0].get("finish_reason", "")
        if finish == "length":
            warnings.append("回复被 max_tokens 截断，可适当调大 deepseek.max_tokens")

        return LlmResult(
            ok=True,
            text=text.strip(),
            elapsed_s=elapsed,
            prompt_tokens=int(usage.get("prompt_tokens", 0)),
            completion_tokens=int(usage.get("completion_tokens", 0)),
            warnings=warnings,
            raw=data,
        )

    return LlmResult(ok=False, err_msg=last_err)


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="DeepSeek 儿童人格 prompt —— 单次诊断")

