/* --------------------------------------------------------------------------
 * 定时器回调
 * -------------------------------------------------------------------------- */

static void on_tick(lv_timer_t *t)
{
    (void)t;
    struct child_face *f = &g_face;
    struct look lk;
    int s = f->s;

    f->tick++;
    look_for(f->state, f->tick, &lk);

    int eh = should_blink(f->state, f->tick) ? (s * 12 / 1000) : (s * lk.eye_h / 1000);
    if (eh < 2) eh = 2;

    int ew = s * 150 / 1000;   /* 眼睛宽度固定 */
    if (ew < 2) ew = 2;

    lv_obj_set_size(f->eye_l, ew, eh);
    lv_obj_set_size(f->eye_r, ew, eh);

    /* 高光：睁眼时显示，闭眼时用隐藏标志（绝不用 0 尺寸） */
    int hi = s * 55 / 1000;
    if (hi < 1) hi = 1;
    if (eh >= s * 40 / 1000) {
        lv_obj_clear_flag(f->hi_l, LV_OBJ_FLAG_HIDDEN);
        lv_obj_clear_flag(f->hi_r, LV_OBJ_FLAG_HIDDEN);
        lv_obj_set_size(f->hi_l, hi, hi);
        lv_obj_set_size(f->hi_r, hi, hi);
    } else {
        lv_obj_add_flag(f->hi_l, LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(f->hi_r, LV_OBJ_FLAG_HIDDEN);
    }

    int mw = s * lk.mouth_w / 1000;
    int mh = s * lk.mouth_h / 1000;
    if (mw < 1) mw = 1;
    if (mh < 1) mh = 1;
    lv_obj_set_size(f->mouth, mw, mh);

    lv_obj_set_style_opa(f->cheek_l, lk.cheek_opa, 0);
    lv_obj_set_style_opa(f->cheek_r, lk.cheek_opa, 0);
}

/* --------------------------------------------------------------------------
 * 对外接口
 * -------------------------------------------------------------------------- */

int child_face_init(void)
{
    struct child_face *f = &g_face;

    if (f->inited) {
        return 0;
    }

    lv_obj_t *scr = lv_scr_act();

