1	/*
2	 * child_face 的主机端测试 —— 不需要板子、不需要 LVGL、不需要网络。
3	 *
4	 * 编译：见同目录 run_tests.sh
5	 *
6	 * 覆盖：
7	 *   1. 初始化成功 / LVGL 未就绪时失败
8	 *   2. 未初始化时的调用安全
9	 *   3. 重复初始化幂等
10	 *   4. 各状态的视觉参数（聆听睁眼、开心嘴张大、说话时嘴动）
11	 *   5. 非法状态被忽略
12	 *   6. 释放后可重新初始化
13	 */
14	
15	#include <stdarg.h>
16	#include <stdio.h>
17	#include <stdlib.h>
18	
19	/* 桩必须在实现之前包含 —— child_face.c 里 #include <lvgl.h> 会命中它 */
20	#include "stubs/lvgl.h"
21	
22	/* 把实现拉进同一编译单元：这样桩里的 static 全局只有一份，记录才一致 */
23	#include "../child_face.c"
24	
25	static int g_fail = 0;
26	static int g_pass = 0;
27	
28	static void CHECK(int cond, const char *fmt, ...)
29	{
30	    va_list ap;
31	    va_start(ap, fmt);
32	    if (cond) {
33	        g_pass++;
34	        printf("    PASS  ");
35	    } else {
36	        g_fail++;
37	        printf("    FAIL  ");
38	    }
39	    vprintf(fmt, ap);
40	    va_end(ap);
41	    printf("\n");
42	}
43	
44	/* 控件创建顺序，见 child_face_init() */
45	enum { I_ROOT = 0, I_EYE_L, I_EYE_R, I_CHEEK_L, I_CHEEK_R, I_MOUTH };
46	
47	/*
48	 * 每个用例开始时调用：把桩和 child_face 的内部状态**都**清干净。
49	 *
50	 * 为什么必须先 deinit 再重置桩
51	 * ----------------------------
52	 * child_face.c 里的 g_face 是 static 全局，会**跨用例残留**。
53	 * 只重置桩是不够的：下一个用例调 child_face_init() 时会撞上
54	 * `if (f->inited) return 0;`，直接返回成功但内部指针仍指向上一轮的控件 ——
55	 * 于是读到的尺寸全是 -1。
56	 *
57	 * （这不是 child_face 的 bug：它就是个单例，且提供了 deinit()。
58	 *   是测试必须自己保证用例之间互不干扰。）
59	 */
60	static void fresh(int screen_ok)
61	{
62	    child_face_deinit();
63	    stub_reset(screen_ok);
64	}
65	
66	int main(void)
67	{
68	    printf("\n===== child_face 主机端测试 =====\n");
69	
70	    /* --- 1. 初始化 ------------------------------------------------------ */
71	    printf("\n[初始化]\n");
72	    {
73	        fresh(1);
74	        int rc = child_face_init();
75	
76	        CHECK(rc == 0, "init 返回 0（实得 %d）", rc);
77	        CHECK(child_face_get_state() == CHILD_FACE_IDLE,
78	              "初始状态为 IDLE");
79	        CHECK(stub_obj_count() == 6,
80	              "创建了 6 个控件：root/眼x2/腮红x2/嘴（实得 %d）", stub_obj_count());
81	        CHECK(stub_timer != NULL, "定时器已创建");
