/*
 * child_face 的主机端测试 —— 不需要板子、不需要 LVGL、不需要网络。
 *
 * 编译：见同目录 run_tests.sh
 *
 * 覆盖：
 *   1. 初始化成功 / LVGL 未就绪时失败
 *   2. 未初始化时的调用安全
 *   3. 重复初始化幂等
 *   4. 各状态的视觉参数（聆听睁眼、开心嘴张大、说话时嘴动）
 *   5. 非法状态被忽略
 *   6. 释放后可重新初始化
 */

#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>

/* 桩必须在实现之前包含 —— child_face.c 里 #include <lvgl.h> 会命中它 */
#include "stubs/lvgl.h"

/* 把实现拉进同一编译单元：这样桩里的 static 全局只有一份，记录才一致 */
#include "../child_face.c"

static int g_fail = 0;
static int g_pass = 0;

static void CHECK(int cond, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    if (cond) {
        g_pass++;
        printf("    PASS  ");
    } else {
        g_fail++;
        printf("    FAIL  ");
    }
    vprintf(fmt, ap);
    va_end(ap);
    printf("\n");
}

/* 控件创建顺序，见 child_face_init() */
enum { I_ROOT = 0, I_EYE_L, I_EYE_R, I_CHEEK_L, I_CHEEK_R, I_MOUTH };

/*
 * 每个用例开始时调用：把桩和 child_face 的内部状态**都**清干净。
 *
 * 为什么必须先 deinit 再重置桩
 * ----------------------------
 * child_face.c 里的 g_face 是 static 全局，会**跨用例残留**。
 * 只重置桩是不够的：下一个用例调 child_face_init() 时会撞上
 * `if (f->inited) return 0;`，直接返回成功但内部指针仍指向上一轮的控件 ——
 * 于是读到的尺寸全是 -1。
 *
 * （这不是 child_face 的 bug：它就是个单例，且提供了 deinit()。
 *   是测试必须自己保证用例之间互不干扰。）
 */
static void fresh(int screen_ok)
{
    child_face_deinit();
    stub_reset(screen_ok);
}

int main(void)
{
    printf("\n===== child_face 主机端测试 =====\n");

    /* --- 1. 初始化 ------------------------------------------------------ */
    printf("\n[初始化]\n");
    {
        fresh(1);
        int rc = child_face_init();

        CHECK(rc == 0, "init 返回 0（实得 %d）", rc);
        CHECK(child_face_get_state() == CHILD_FACE_IDLE,
              "初始状态为 IDLE");
        CHECK(stub_obj_count() == 6,
              "创建了 6 个控件：root/眼x2/腮红x2/嘴（实得 %d）", stub_obj_count());
        CHECK(stub_timer != NULL, "定时器已创建");
    }

    /* --- 2. LVGL 未就绪 -------------------------------------------------- */
    printf("\n[LVGL 未就绪（无 screen）]\n");
    {
        fresh(0);
        int rc = child_face_init();

        CHECK(rc == -1, "init 返回 -1（实得 %d）", rc);
        CHECK(child_face_get_state() == -1, "未初始化时 get_state 返回 -1");
    }

    /* --- 3. 未初始化时调用不应崩溃 -------------------------------------- */
    printf("\n[未初始化时的调用安全]\n");
    {
        fresh(1);
        child_face_set_state(CHILD_FACE_LISTENING);  /* 不应崩 */
        child_face_deinit();                          /* 不应崩 */
        CHECK(child_face_get_state() == -1, "仍处于未初始化状态");
        CHECK(1, "未初始化时 set_state / deinit 均未崩溃");
    }

    /* --- 4. 重复初始化幂等 ---------------------------------------------- */
    printf("\n[重复初始化]\n");
    {
        fresh(1);
        child_face_init();
        int n1 = stub_obj_count();
        child_face_init();
        int n2 = stub_obj_count();

        CHECK(n1 == n2, "重复 init 不重复创建控件（%d -> %d）", n1, n2);
    }

    /* --- 5. 聆听：眼睛睁大 ---------------------------------------------- */
    printf("\n[状态 -> 视觉：LISTENING 睁大眼睛]\n");
    {
        fresh(1);
        child_face_init();

        child_face_set_state(CHILD_FACE_LISTENING);
        stub_tick();

        int w = 0, h = 0;
        stub_obj_size(I_EYE_L, &w, &h);
        CHECK(h == EYE_H + 6, "眼睛高度 = EYE_H+6 = %d（实得 %d）", EYE_H + 6, h);

        stub_obj_size(I_MOUTH, &w, &h);
        CHECK(w == 22 && h == 10, "嘴 = 22x10（实得 %dx%d）", w, h);
    }

    /* --- 6. 开心：嘴张大 ------------------------------------------------ */
    printf("\n[状态 -> 视觉：HAPPY 嘴张大]\n");
    {
        fresh(1);
        child_face_init();

        child_face_set_state(CHILD_FACE_HAPPY);
        stub_tick();

        int w = 0, h = 0;
        stub_obj_size(I_MOUTH, &w, &h);
        CHECK(w == MOUTH_W_MAX && h == 22,
              "嘴张大到 %dx22（实得 %dx%d）", MOUTH_W_MAX, w, h);

        /* 开心时腮红应该最明显 —— 这是孩子最容易辨认的"情绪信号" */
        CHECK(stub_obj_opa(I_CHEEK_L) == LV_OPA_100,
              "腮红不透明度 = 100（实得 %d）", stub_obj_opa(I_CHEEK_L));
    }

    /* --- 7. 说话：嘴会动 ------------------------------------------------ */
    printf("\n[状态 -> 视觉：SPEAKING 嘴巴开合]\n");
    {
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_SPEAKING);

        int seen[12];
        int n = 0;
        for (int i = 0; i < 8; i++) {
            stub_tick();
            int w = 0, h = 0;
            stub_obj_size(I_MOUTH, &w, &h);
            seen[n++] = h;
        }

        int distinct = 0;
        for (int i = 0; i < n; i++) {
            int is_new = 1;
            for (int j = 0; j < i; j++) {
                if (seen[j] == seen[i]) { is_new = 0; break; }
            }
            if (is_new) { distinct++; }
        }

        CHECK(distinct >= 3,
              "8 次 tick 内嘴高度出现 >=3 种不同值，说明在动（实得 %d 种）", distinct);

        int mn = seen[0], mx = seen[0];
        for (int i = 1; i < n; i++) {
            if (seen[i] < mn) { mn = seen[i]; }
            if (seen[i] > mx) { mx = seen[i]; }
        }
        CHECK(mn >= MOUTH_H_MIN && mx <= MOUTH_H_MAX,
              "嘴高度始终在 [%d, %d] 区间内（实得 [%d, %d]）",
              MOUTH_H_MIN, MOUTH_H_MAX, mn, mx);
    }

    /* --- 8. 非法状态被忽略 ---------------------------------------------- */
    printf("\n[非法状态]\n");
    {
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_LISTENING);

        child_face_set_state(999);
        CHECK(child_face_get_state() == CHILD_FACE_LISTENING,
              "越界状态被忽略，保持原状态");

        child_face_set_state(-1);
        CHECK(child_face_get_state() == CHILD_FACE_LISTENING,
              "负数状态被忽略，保持原状态");
    }

    /* --- 9. 释放后可重新初始化 ------------------------------------------ */
    printf("\n[释放与重建]\n");
    {
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_HAPPY);
        child_face_deinit();

        CHECK(child_face_get_state() == -1, "deinit 后 get_state 返回 -1");
        CHECK(stub_timer == NULL, "deinit 后定时器已删除");

        int rc = child_face_init();
        CHECK(rc == 0, "deinit 后可以重新 init（实得 %d）", rc);
        CHECK(child_face_get_state() == CHILD_FACE_IDLE, "重建后状态回到 IDLE");
    }

    /* --- 汇总 ------------------------------------------------------------ */
    printf("\n===== 结果：%s（通过 %d，失败 %d）=====\n\n",
           g_fail == 0 ? "全部通过" : "存在失败", g_pass, g_fail);

    return g_fail == 0 ? 0 : 1;
}

