1	/*
2	 * 极简 LVGL 桩 —— 仅供主机端测试使用，不是真的 LVGL。
3	 *
4	 * 为什么用"记录调用的桩"，而不是去测内部函数
5	 * ------------------------------------------
6	 * child_face.c 里的 look_for() / should_blink() 是 static，外部测不到。
7	 * 与其把它们改成非 static（那会污染对外接口），不如**通过真实 API 验证行为**：
8	 * 桩记录下 child_face 对每个控件下发的尺寸/透明度，测试据此断言。
9	 *
10	 * 这样测的是"用户真正会看到的东西"，比测一个内部 helper 更有意义。
11	 *
12	 * 为什么可以写成 header-only + static 全局
13	 * --------------------------------------
14	 * 前提：**只有一个编译单元**包含本文件。
15	 * test_child_face.c 用 `#include "../child_face.c"` 把实现拉进同一个 TU，
16	 * 所以成立。换来的是：不需要额外的 .c，也不需要链接步骤。
17	 */
18	
19	#pragma once
20	
21	#include <stdint.h>
22	#include <string.h>
23	
24	#define STUB_MAX_OBJ 16
25	
26	typedef struct lv_obj {
27	    int w;
28	    int h;
29	    int opa;      /* 最近一次 set_style_opa 下发的值 */
30	} lv_obj_t;
31	
32	typedef struct lv_timer {
33	    void (*cb)(struct lv_timer *);
34	} lv_timer_t;
35	
36	typedef struct {
37	    uint8_t r;
38	    uint8_t g;
39	    uint8_t b;
40	} lv_color_t;
41	
42	static lv_color_t lv_color_hex(uint32_t v)
43	{
44	    lv_color_t c;
45	    c.r = (uint8_t)(v >> 16);
46	    c.g = (uint8_t)(v >> 8);
47	    c.b = (uint8_t)v;
48	    return c;
49	}
50	
51	#define LV_OPA_0       0
52	#define LV_OPA_30      77
53	#define LV_OPA_40      102
54	#define LV_OPA_60      153
55	#define LV_OPA_80      204
56	#define LV_OPA_100     255
57	#define LV_OPA_COVER   255
58	#define LV_RADIUS_CIRCLE 0x7FFF
59	#define LV_ALIGN_CENTER  0
60	
61	/* ------------------------------------------------------------------ 记录状态 */
62	
63	static lv_obj_t   stub_objs[STUB_MAX_OBJ];
64	static int        stub_nobj;
65	static int        stub_screen_ok = 1;   /* 置 0 可模拟"LVGL 未就绪" */
66	static lv_timer_t stub_timer_obj;
67	static lv_timer_t *stub_timer;
68	
69	/* 让测试能重置/读取 */
70	static void stub_reset(int screen_ok)
71	{
72	    memset(stub_objs, 0, sizeof(stub_objs));
73	    stub_nobj      = 0;
74	    stub_screen_ok = screen_ok;
75	    stub_timer     = NULL;
76	    memset(&stub_timer_obj, 0, sizeof(stub_timer_obj));
77	}
78	
79	static int stub_obj_count(void) { return stub_nobj; }
80	
81	/* 按创建顺序取控件尺寸。顺序见 child_face_init：
82	 *   0=root 1=eye_l 2=eye_r 3=cheek_l 4=cheek_r 5=mouth */
83	static void stub_obj_size(int idx, int *w, int *h)
84	{
85	    if (idx < 0 || idx >= stub_nobj) { *w = *h = -1; return; }
86	    *w = stub_objs[idx].w;
87	    *h = stub_objs[idx].h;
88	}
89	
90	static int stub_obj_opa(int idx)
91	{
92	    return (idx >= 0 && idx < stub_nobj) ? stub_objs[idx].opa : -1;
93	}
94	
95	/* 手动推进一次定时器回调 */
96	static void stub_tick(void)
97	{
98	    if (stub_timer != NULL && stub_timer->cb != NULL) {
99	        stub_timer->cb(stub_timer);
100	    }
101	}
102	
103	/* ------------------------------------------------------------------ LVGL API */
104	
105	static lv_obj_t *lv_scr_act(void)
106	{
107	    static lv_obj_t scr;
108	    return stub_screen_ok ? &scr : NULL;
109	}
110	
111	static lv_obj_t *lv_obj_create(lv_obj_t *parent)
112	{
113	    (void)parent;
114	    if (stub_nobj >= STUB_MAX_OBJ) {
115	        return NULL;
116	    }
117	    memset(&stub_objs[stub_nobj], 0, sizeof(lv_obj_t));
118	    return &stub_objs[stub_nobj++];
119	}
120	
121	static void lv_obj_delete(lv_obj_t *o)                    { (void)o; }
122	static void lv_obj_remove_style_all(lv_obj_t *o)          { (void)o; }
123	static void lv_obj_center(lv_obj_t *o)                    { (void)o; }
124	static void lv_obj_align(lv_obj_t *o, int a, int x, int y){ (void)o; (void)a; (void)x; (void)y; }
125	static void lv_obj_set_style_bg_color(lv_obj_t *o, lv_color_t c, int s)
126	{
127	    (void)o; (void)c; (void)s;
128	}
129	static void lv_obj_set_style_bg_opa(lv_obj_t *o, int opa, int s)
130	{
131	    (void)s;
132	    if (o != NULL) { o->opa = opa; }
133	}
134	static void lv_obj_set_style_radius(lv_obj_t *o, int r, int s) { (void)o; (void)r; (void)s; }
135	
136	static void lv_obj_set_size(lv_obj_t *o, int w, int h)
137	{
138	    if (o == NULL) { return; }
139	    o->w = w;
140	    o->h = h;
141	}
142	
143	static void lv_obj_set_height(lv_obj_t *o, int h)
144	{
145	    if (o == NULL) { return; }
146	    o->h = h;
147	}
148	
149	static void lv_obj_set_style_opa(lv_obj_t *o, int opa, int sel)
150	{
151	    (void)sel;
152	    if (o == NULL) { return; }
153	    o->opa = opa;
154	}
155	
156	static lv_timer_t *lv_timer_create(void (*cb)(lv_timer_t *), uint32_t period, void *user)
157	{
158	    (void)period;
159	    (void)user;
160	    if (cb == NULL) { return NULL; }
161	    stub_timer_obj.cb = cb;
162	    stub_timer = &stub_timer_obj;
163	    return stub_timer;
164	}
165	
166	static void lv_timer_delete(lv_timer_t *t)
167	{
168	    (void)t;
169	    stub_timer = NULL;
170	}
