int child_face_init(void)
{
    struct child_face *f = &g_face;

    if (f->inited) {
        return 0;
    }

    lv_obj_t *scr = lv_scr_act();
    if (scr == NULL) {
        return -1;
    }

    lv_display_t *disp = lv_disp_get_default();
    int W = lv_display_get_horizontal_resolution(disp);
    int H = lv_display_get_vertical_resolution(disp);
    int s = (W < H) ? W : H;      /* 短边作基准 */
    if (s <= 0) {
        s = 240;
    }
    f->s = s;

    /* 根控件：占满整屏（自适应，消除黑边） */
    f->root = lv_obj_create(scr);
    if (f->root == NULL) {
        return -1;
    }
    lv_obj_remove_style_all(f->root);
    lv_obj_set_size(f->root, W, H);
    lv_obj_set_pos(f->root, 0, 0);
    lv_obj_set_style_bg_color(f->root, C_BG, 0);
    lv_obj_set_style_bg_opa(f->root, LV_OPA_COVER, 0);

    /* 头：一个大圆 */
    f->head = lv_obj_create(f->root);
    if (f->head == NULL) {
        return -1;
    }
    lv_obj_remove_style_all(f->head);
    int hd = s * 72 / 100;
    lv_obj_set_size(f->head, hd, hd);
    lv_obj_set_style_bg_color(f->head, C_HEAD, 0);
    lv_obj_set_style_bg_opa(f->head, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(f->head, LV_RADIUS_CIRCLE, 0);
    lv_obj_center(f->head);
    lv_obj_set_y(f->head, -s * 2 / 100);

    /* 眼睛（两眼中心在上半部分） */
    f->eye_l = lv_obj_create(f->head);
    f->eye_r = lv_obj_create(f->head);
    if (f->eye_l == NULL || f->eye_r == NULL) {
        return -1;
    }
    lv_obj_remove_style_all(f->eye_l);
    lv_obj_remove_style_all(f->eye_r);
    int ew = s * 15 / 100;
    int eh = s * 17 / 100;
    int gap = s * 24 / 100;
    int ey = -s * 7 / 100;
    lv_obj_set_size(f->eye_l, ew, eh);
    lv_obj_set_size(f->eye_r, ew, eh);
    lv_obj_set_style_bg_color(f->eye_l, C_EYE, 0);
    lv_obj_set_style_bg_color(f->eye_r, C_EYE, 0);
    lv_obj_set_style_bg_opa(f->eye_l, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_opa(f->eye_r, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(f->eye_l, LV_RADIUS_CIRCLE, 0);
    lv_obj_set_style_radius(f->eye_r, LV_RADIUS_CIRCLE, 0);
    lv_obj_align(f->eye_l, LV_ALIGN_CENTER, -gap / 2, ey);
    lv_obj_align(f->eye_r, LV_ALIGN_CENTER,  gap / 2, ey);

    /* 眼神高光（白色小圆，贴眼睛左上） */
    f->hi_l = lv_obj_create(f->eye_l);
    f->hi_r = lv_obj_create(f->eye_r);
    if (f->hi_l == NULL || f->hi_r == NULL) {
        return -1;
    }
    lv_obj_remove_style_all(f->hi_l);
    lv_obj_remove_style_all(f->hi_r);
    int hi = s * 5 / 100;
    lv_obj_set_size(f->hi_l, hi, hi);

