/*
 * 极简 LVGL 桩 —— 仅供主机端测试使用，不是真的 LVGL。
 *
 * 为什么用"记录调用的桩"，而不是去测内部函数
 * ------------------------------------------
 * child_face.c 里的 look_for() / should_blink() 是 static，外部测不到。
 * 与其把它们改成非 static（那会污染对外接口），不如**通过真实 API 验证行为**：
 * 桩记录下 child_face 对每个控件下发的尺寸/透明度，测试据此断言。
 *
 * 这样测的是"用户真正会看到的东西"，比测一个内部 helper 更有意义。
 *
 * 为什么可以写成 header-only + static 全局
 * --------------------------------------
 * 前提：**只有一个编译单元**包含本文件。
 * test_child_face.c 用 `#include "../child_face.c"` 把实现拉进同一个 TU，
 * 所以成立。换来的是：不需要额外的 .c，也不需要链接步骤。
 */

#pragma once

#include <stdint.h>
#include <string.h>

#define STUB_MAX_OBJ 16

typedef struct lv_obj {
    int w;
    int h;
    int opa;      /* 最近一次 set_style_opa 下发的值 */
} lv_obj_t;

typedef struct lv_timer {
    void (*cb)(struct lv_timer *);
} lv_timer_t;

typedef struct {
    uint8_t r;
    uint8_t g;
    uint8_t b;
} lv_color_t;

static lv_color_t lv_color_hex(uint32_t v)
{
    lv_color_t c;
    c.r = (uint8_t)(v >> 16);
    c.g = (uint8_t)(v >> 8);
    c.b = (uint8_t)v;
    return c;
}

#define LV_OPA_0       0
#define LV_OPA_30      77
#define LV_OPA_40      102
#define LV_OPA_60      153
#define LV_OPA_80      204
#define LV_OPA_100     255
#define LV_OPA_COVER   255
#define LV_RADIUS_CIRCLE 0x7FFF
#define LV_ALIGN_CENTER  0
#define LV_ALIGN_TOP_LEFT 4        /* 真实值不重要，桩只记录不解释 */

/* ------------------------------------------------------------------ 记录状态 */

static lv_obj_t   stub_objs[STUB_MAX_OBJ];
static int        stub_nobj;
static int        stub_screen_ok = 1;   /* 置 0 可模拟"LVGL 未就绪" */
static lv_timer_t stub_timer_obj;
static lv_timer_t *stub_timer;

/* 屏幕尺寸。stub 默认 0 —— child_face.c 里 `s<=0` 会回落到 240，
 * 所以测试里要用 stub_screen_size() 显式设定，才能得到确定值。 */
static int stub_scr_w = 0;
static int stub_scr_h = 0;

/* 控件位置。child_face 用 align/set_pos/set_y 摆放元素，
 * 桩记下来，测试可以断言"没有元素跑到屏幕外" */
typedef struct {
    int align;
    int x;
    int y;
} stub_pos_t;

static stub_pos_t stub_pos[STUB_MAX_OBJ];

/* 让测试能重置/读取 */
static void stub_reset(int screen_ok)
{
    memset(stub_objs, 0, sizeof(stub_objs));
    memset(stub_pos, 0, sizeof(stub_pos));
    stub_nobj      = 0;
    stub_screen_ok = screen_ok;
    stub_timer     = NULL;
    stub_scr_w     = 0;
    stub_scr_h     = 0;
    memset(&stub_timer_obj, 0, sizeof(stub_timer_obj));
}

/* 测试专用：设定屏幕尺寸（px）。必须在 child_face_init() 之前调用 */
static void stub_screen_size(int w, int h)
{
    stub_scr_w = w;
    stub_scr_h = h;
}

static int stub_obj_count(void) { return stub_nobj; }

/* 按创建顺序取控件尺寸。顺序见 child_face_init */
static void stub_obj_size(int idx, int *w, int *h)
{
    if (idx < 0 || idx >= stub_nobj) { *w = *h = -1; return; }
    *w = stub_objs[idx].w;
    *h = stub_objs[idx].h;
}

static int stub_obj_opa(int idx)
{
    return (idx >= 0 && idx < stub_nobj) ? stub_objs[idx].opa : -1;
}

static stub_pos_t stub_obj_pos(int idx)
{
    stub_pos_t empty;
    empty.align = 0; empty.x = 0; empty.y = 0;
    if (idx < 0 || idx >= stub_nobj) { return empty; }
    return stub_pos[idx];
}

/* 控件中心是否落在屏幕内 —— 用来兜住"元素跑出屏幕"这种回归 */
static int stub_obj_on_screen(int idx)
{
    if (idx < 0 || idx >= stub_nobj) { return 0; }
    stub_pos_t p = stub_pos[idx];
    /* align 模式下桩记的是相对父中心的偏移，抽象判断：
     * 只要没被设成离谱的大偏移就算在屏内 */
    if (p.x < -stub_scr_w || p.x > stub_scr_w) { return 0; }
    if (p.y < -stub_scr_h || p.y > stub_scr_h) { return 0; }
    return 1;
}

/* 手动推进一次定时器回调 */
static void stub_tick(void)
{
    if (stub_timer != NULL && stub_timer->cb != NULL) {
        stub_timer->cb(stub_timer);
    }
}

/* ------------------------------------------------------------------ LVGL API */

static lv_obj_t *lv_scr_act(void)
{
    static lv_obj_t scr;
    return stub_screen_ok ? &scr : NULL;
}

static lv_obj_t *lv_obj_create(lv_obj_t *parent)
{
    (void)parent;
    if (stub_nobj >= STUB_MAX_OBJ) {
        return NULL;
    }
    memset(&stub_objs[stub_nobj], 0, sizeof(lv_obj_t));
    return &stub_objs[stub_nobj++];
}

static void lv_obj_delete(lv_obj_t *o)                    { (void)o; }
static void lv_obj_remove_style_all(lv_obj_t *o)          { (void)o; }
static void lv_obj_center(lv_obj_t *o)                    { (void)o; }
static void lv_obj_align(lv_obj_t *o, int a, int x, int y){ (void)o; (void)a; (void)x; (void)y; }
static void lv_obj_set_style_bg_color(lv_obj_t *o, lv_color_t c, int s)
{
    (void)o; (void)c; (void)s;
}
static void lv_obj_set_style_bg_opa(lv_obj_t *o, int opa, int s)
{
    (void)s;
    if (o != NULL) { o->opa = opa; }
}
static void lv_obj_set_style_radius(lv_obj_t *o, int r, int s) { (void)o; (void)r; (void)s; }

static void lv_obj_set_size(lv_obj_t *o, int w, int h)
{
    if (o == NULL) { return; }
    o->w = w;
    o->h = h;
}

static void lv_obj_set_height(lv_obj_t *o, int h)
{
    if (o == NULL) { return; }
    o->h = h;
}

static void lv_obj_set_style_opa(lv_obj_t *o, int opa, int sel)
{
    (void)sel;
    if (o == NULL) { return; }
    o->opa = opa;
}

static lv_timer_t *lv_timer_create(void (*cb)(lv_timer_t *), uint32_t period, void *user)
{
    (void)period;
    (void)user;
    if (cb == NULL) { return NULL; }
    stub_timer_obj.cb = cb;
    stub_timer = &stub_timer_obj;
    return stub_timer;
}

static void lv_timer_delete(lv_timer_t *t)
{
    (void)t;
    stub_timer = NULL;
}

/* -------------------------------------------------- LVGL 9 的 display 接口 */

typedef struct lv_display {
    int hor;
    int ver;
} lv_display_t;

static lv_display_t stub_disp;
static lv_display_t *lv_disp_get_default(void)
{
    stub_disp.hor = stub_scr_w;
    stub_disp.ver = stub_scr_h;
    return &stub_disp;
}

static int lv_display_get_horizontal_resolution(lv_display_t *d)
{
    return (d != NULL) ? d->hor : 0;
}

static int lv_display_get_vertical_resolution(lv_display_t *d)
{
    return (d != NULL) ? d->ver : 0;
}

/* -------------------------------------------------- 摆放（记录 align/偏移）*/

static void lv_obj_align_obj(void) { }   /* 占位，防止误用 */

static void lv_obj_align(lv_obj_t *o, int a, int x, int y)
{
    if (o == NULL) { return; }
    /* 反查控件索引，把偏移记进 stub_pos */
    for (int i = 0; i < stub_nobj; i++) {
        if (&stub_objs[i] == o) {
            stub_pos[i].align = a;
            stub_pos[i].x = x;
            stub_pos[i].y = y;
            return;
        }
    }
}

static void lv_obj_set_pos(lv_obj_t *o, int x, int y)
{
    if (o == NULL) { return; }
    for (int i = 0; i < stub_nobj; i++) {
        if (&stub_objs[i] == o) {
            stub_pos[i].x = x;
            stub_pos[i].y = y;
            return;
        }
    }
}

static void lv_obj_set_y(lv_obj_t *o, int y)
{
    if (o == NULL) { return; }
    for (int i = 0; i < stub_nobj; i++) {
        if (&stub_objs[i] == o) {
            stub_pos[i].y += y;
            return;
        }
    }
}

