 * 数值是**推定值，未经上板验证**（见 child_face.h 的告警）。
 * 设计约束：只有 4 个可用维度，所以每个新表情都要在
 * (eye_h, mouth_w, mouth_h, cheek_opa) 上和所有既有表情拉开可辨差距。
 * ------------------------------------------------------------------ */

case CHILD_FACE_CURIOUS:
    /* 眼瞪到最大（比 LISTENING 的 200 还大），嘴收到很小 ——
     * 表现"凑过来看"的姿态 */
    out->eye_h    = 218;
    out->mouth_w  = 62;
    out->mouth_h  = 42;
    out->cheek_opa = LV_OPA_45;
    break;

case CHILD_FACE_SURPRISED:
    /* 眼与 CURIOUS 同档，但嘴收得比它窄得多、更高 —— 圆嘴 */
    out->eye_h    = 225;
    out->mouth_w  = 38;
    out->mouth_h  = 40;
    out->cheek_opa = LV_OPA_65;
    break;

case CHILD_FACE_CONFUSED:
    /* 眼比 IDLE 略眯，嘴小而偏圆 —— "嗯？" 的那一声。
     * 与 SAD 的区别：SAD 是宽扁嘴，这里嘴高明显大于嘴宽 */
    out->eye_h    = 140;
    out->mouth_w  = 42;
    out->mouth_h  = 38;
    out->cheek_opa = LV_OPA_55;
    break;

case CHILD_FACE_SHY:
    /* 垂眼 + 腮红全表最浓（LV_OPA_COVER 是满值）*/
    out->eye_h    = 92;
    out->mouth_w  = 52;
    out->mouth_h  = 16;
    out->cheek_opa = LV_OPA_COVER;
    break;

case CHILD_FACE_PROUD:
    /* 眯眯眼，但嘴比 SHY 宽得多、且比 HAPPY 收敛 —— 抿嘴笑 */
    out->eye_h    = 85;
    out->mouth_w  = 120;
    out->mouth_h  = 26;
    out->cheek_opa = LV_OPA_95;
    break;

case CHILD_FACE_SAD:
    /* 眼半垂，嘴宽而扁 —— 与 CONFUSED 的小圆嘴正好相反 */
    out->eye_h    = 118;
    out->mouth_w  = 88;
    out->mouth_h  = 15;
    out->cheek_opa = LV_OPA_45;
    break;

