        child_face_set_state(CHILD_FACE_LISTENING);  /* 不应崩 */
        child_face_deinit();                          /* 不应崩 */
        CHECK(child_face_get_state() == -1, "仍处于未初始化状态");
        CHECK(1, "未初始化时 set_state / deinit 均未崩溃");
    }

    /* --- 4. 重复初始化幂等 ---------------------------------------------- */
    printf("\n[重复初始化]\n");
    {
        fresh(1);
        child_face_init();
        int n1 = stub_obj_count();
        child_face_init();
        int n2 = stub_obj_count();

        CHECK(n1 == n2, "重复 init 不重复创建控件（%d -> %d）", n1, n2);
    }

    /* --- 5. 状态 -> 视觉：相对关系 ---------------------------------------
     * 这里断言的是"可感知的相对差异"，而不是绝对像素。
     * 绝对像素会随屏幕尺寸变，而"聆听比待机眼更大"这个性质不该变。
     * ------------------------------------------------------------------ */
    printf("\n[状态 -> 视觉：相对关系]\n");
    {
        int s = SCR_W;   /* 短边 */

        /* 待机基准 */
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_IDLE);
        int idle_ew, idle_eh, idle_mw, idle_mh;
        stub_tick();
        stub_obj_size(I_EYE_L, &idle_ew, &idle_eh);
        stub_obj_size(I_MOUTH, &idle_mw, &idle_mh);

        CHECK(idle_eh == s * 170 / 1000,
              "IDLE 眼高 = s*170/1000 = %d（实得 %d）", s * 170 / 1000, idle_eh);

        /* 聆听：眼睛应比待机更大 */
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_LISTENING);
        int l_ew, l_eh, l_mw, l_mh;
        stub_tick();
        stub_obj_size(I_EYE_L, &l_ew, &l_eh);
        stub_obj_size(I_MOUTH, &l_mw, &l_mh);

        CHECK(l_eh > idle_eh,
              "LISTENING 眼睛比 IDLE 更大（%d > %d）", l_eh, idle_eh);
        CHECK(l_eh == s * 200 / 1000,
              "LISTENING 眼高 = s*200/1000 = %d（实得 %d）", s * 200 / 1000, l_eh);
        CHECK(l_mw > idle_mw && l_mh > idle_mh,
              "LISTENING 嘴比 IDLE 更大（嘴 %dx%d vs %dx%d）",
              l_mw, l_mh, idle_mw, idle_mh);

        /* 开心：眯眼 + 嘴张大 + 腮红最浓 */
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_HAPPY);
        int h_ew, h_eh, h_mw, h_mh;
        stub_tick();
        stub_obj_size(I_EYE_L, &h_ew, &h_eh);
        stub_obj_size(I_MOUTH, &h_mw, &h_mh);

        CHECK(h_eh < idle_eh,
              "HAPPY 眼睛比 IDLE 更小（眯眼，%d < %d）", h_eh, idle_eh);
        CHECK(h_mw > l_mw && h_mh > l_mh,
              "HAPPY 嘴是全表最大的（%dx%d 超过 LISTENING %dx%d）",
              h_mw, h_mh, l_mw, l_mh);
        CHECK(h_mw == s * 185 / 1000,
              "HAPPY 嘴宽 = s*185/1000 = %d（实得 %d）", s * 185 / 1000, h_mw);
        CHECK(stub_obj_opa(I_CHEEK_L) == LV_OPA_100,
              "HAPPY 腮红不透明度 = 100（实得 %d）", stub_obj_opa(I_CHEEK_L));

        /* 困倦：眼半垂，腮红最淡 */
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_SLEEPY);
        int s_eh, s_mw, s_mh;
        stub_tick();
        stub_obj_size(I_EYE_L, &s_eh, &s_eh);
        stub_obj_size(I_MOUTH, &s_mw, &s_mh);
        CHECK(s_eh < h_eh + 40 && stub_obj_opa(I_CHEEK_L) == LV_OPA_30,
              "SLEEPY 腮红 = 30（最淡，实得 %d）", stub_obj_opa(I_CHEEK_L));
    }

    /* --- 6. 说话：嘴会动 ------------------------------------------------ */
    printf("\n[状态 -> 视觉：SPEAKING 嘴巴开合]\n");
    {
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_SPEAKING);

        int seen[16];
        int n = 0;
        for (int i = 0; i < 12; i++) {
            int w = 0, h = 0;
            stub_tick();
            stub_obj_size(I_MOUTH, &w, &h);
            if (n < 16) { seen[n++] = h; }
        }

        int distinct = 0;
        for (int i = 0; i < n; i++) {
            int is_new = 1;
            for (int j = 0; j < i; j++) {
                if (seen[j] == seen[i]) { is_new = 0; break; }
            }
            if (is_new) { distinct++; }
        }

        CHECK(distinct >= 3,
              "12 次 tick 内嘴高度出现 >=3 种不同值，说明在动（实得 %d 种）", distinct);

        int mn = seen[0], mx = seen[0];
        for (int i = 1; i < n; i++) {
            if (seen[i] < mn) { mn = seen[i]; }
            if (seen[i] > mx) { mx = seen[i]; }
        }
        CHECK(mn < mx, "嘴高度确实有波动（[%d, %d]）", mn, mx);
    }

    /* --- 7. ★ v2：新表情彼此可辨 ----------------------------------------
     * 这是"多加几个表情"的验收：如果两个状态算出来的四元组完全相同，
     * 那它们在孩子眼里就是同一张脸 —— 加等于没加。
     * ------------------------------------------------------------------ */
    printf("\n[v2：12 个状态两两可辨]\n");
    {
        const int states[] = {
            CHILD_FACE_IDLE, CHILD_FACE_LISTENING, CHILD_FACE_THINKING,
            CHILD_FACE_SPEAKING, CHILD_FACE_HAPPY, CHILD_FACE_SLEEPY,
            CHILD_FACE_CURIOUS, CHILD_FACE_SURPRISED, CHILD_FACE_CONFUSED,
            CHILD_FACE_SHY, CHILD_FACE_PROUD, CHILD_FACE_SAD,
        };
        const int n = (int)(sizeof(states) / sizeof(states[0]));

        /* THINKING / SPEAKING 是动画态（参数随 tick 变），
         * 取 tick=1 时的快照参与比对，避免把动画误判成"重复"。 */
        int dup = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int ei = 0, mi = 0, hi = 0, oj = 0, mj = 0, hj = 0;

                fresh(1);
                child_face_init();
                child_face_set_state(states[i]);
                stub_tick();
                stub_obj_size(I_EYE_L, &ei, &ei);
                stub_obj_size(I_MOUTH, &mi, &hi);
                int ci = stub_obj_opa(I_CHEEK_L);

                fresh(1);
                child_face_init();
                child_face_set_state(states[j]);
                stub_tick();
                stub_obj_size(I_EYE_L, &oj, &oj);
                stub_obj_size(I_MOUTH, &mj, &hj);
                int cj = stub_obj_opa(I_CHEEK_L);

                if (ei == oj && mi == mj && hi == hj && ci == cj) {
                    dup++;
                    printf("    FAIL  状态 %d 与 %d 视觉完全相同\n", states[i], states[j]);
                }
            }
        }

        CHECK(dup == 0, "任意两个状态的四元组都不同（重复对数 = %d）", dup);
        CHECK(CHILD_FACE__COUNT == n,
              "CHILD_FACE__COUNT == %d（实得 %d，枚举与测试列表是否同步）",
              n, CHILD_FACE__COUNT);
    }

    /* --- 8. 元素不出屏幕 ------------------------------------------------ */
    printf("\n[元素不出屏幕]\n");
    {
        fresh(1);
        child_face_init();
        int bad = 0;
        for (int i = 0; i < stub_obj_count(); i++) {
            if (!stub_obj_on_screen(i)) {
                bad++;
                printf("    FAIL  控件 %d 的摆放偏移越界\n", i);
            }
        }
        CHECK(bad == 0, "所有 %d 个控件的摆放偏移都在合理范围（越界 %d 个）",
              stub_obj_count(), bad);
    }

    /* --- 9. 非法状态被忽略 ---------------------------------------------- */
    printf("\n[非法状态]\n");
    {
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_LISTENING);

        /* 新上界：刚加进枚举的合法状态必须被接受 */
        child_face_set_state(CHILD_FACE_SAD);
        CHECK(child_face_get_state() == CHILD_FACE_SAD,
              "新状态 SAD 被接受（实得 %d）", child_face_get_state());

        child_face_set_state(CHILD_FACE_LISTENING);
        child_face_set_state(CHILD_FACE__COUNT);
        CHECK(child_face_get_state() == CHILD_FACE_LISTENING,
              "== COUNT 的越界值被忽略，保持原状态");
        child_face_set_state(999);
        CHECK(child_face_get_state() == CHILD_FACE_LISTENING,
              "越界状态被忽略，保持原状态");
        child_face_set_state(-1);
        CHECK(child_face_get_state() == CHILD_FACE_LISTENING,
              "负数状态被忽略，保持原状态");
    }

    /* --- 10. 释放后可重新初始化 ------------------------------------------ */
    printf("\n[释放与重建]\n");
    {
        fresh(1);
        child_face_init();
        child_face_set_state(CHILD_FACE_HAPPY);
        child_face_deinit();

        CHECK(child_face_get_state() == -1, "deinit 后 get_state 返回 -1");
        CHECK(stub_timer == NULL, "deinit 后定时器已删除");

        int rc = child_face_init();
        CHECK(rc == 0, "deinit 后可以重新 init（实得 %d）", rc);
        CHECK(child_face_get_state() == CHILD_FACE_IDLE, "重建后状态回到 IDLE");
    }

    /* --- 汇总 ------------------------------------------------------------ */
    printf("\n===== 结果：%s（通过 %d，失败 %d）=====\n\n",
           g_fail == 0 ? "全部通过" : "存在失败", g_pass, g_fail);

    return g_fail == 0 ? 0 : 1;
}

