/*
 * 极简 LVGL 桩 —— 仅供主机端测试使用，不是真的 LVGL。
 *
 * 为什么用"记录调用的桩"，而不是去测内部函数
 * ------------------------------------------
 * child_face.c 里的 look_for() / should_blink() 是 static，外部测不到。
 * 与其把它们改成非 static（那会污染对外接口），不如**通过真实 API 验证行为**：
 * 桩记录下 child_face 对每个控件下发的尺寸/透明度，测试据此断言。
 *
 * 这样测的是"用户真正会看到的东西"，比测一个内部 helper 更有意义。
 *
 * 为什么可以写成 header-only + static 全局
 * --------------------------------------
 * 前提：**只有一个编译单元**包含本文件。
 * test_child_face.c 用 `#include "../child_face.c"` 把实现拉进同一个 TU，
 * 所以成立。换来的是：不需要额外的 .c，也不需要链接步骤。
 */

#pragma once

#include <stdint.h>
#include <string.h>

#define STUB_MAX_OBJ 16

typedef struct lv_obj {
    int w;
    int h;
    int opa;      /* 最近一次 set_style_opa 下发的值 */
} lv_obj_t;

typedef struct lv_timer {
    void (*cb)(struct lv_timer *);
} lv_timer_t;

typedef struct {
    uint8_t r;
    uint8_t g;
    uint8_t b;
} lv_color_t;

static lv_color_t lv_color_hex(uint32_t v)
{
    lv_color_t c;
    c.r = (uint8_t)(v >> 16);
    c.g = (uint8_t)(v >> 8);
    c.b = (uint8_t)v;
    return c;
}

#define LV_OPA_0       0
#define LV_OPA_30      77
#define LV_OPA_40      102
#define LV_OPA_60      153
#define LV_OPA_80      204
#define LV_OPA_100     255
#define LV_OPA_COVER   255
#define LV_RADIUS_CIRCLE 0x7FFF
#define LV_ALIGN_CENTER  0
#define LV_ALIGN_TOP_LEFT 4        /* 真实值不重要，桩只记录不解释 */

/* ------------------------------------------------------------------ 记录状态 */

static lv_obj_t   stub_objs[STUB_MAX_OBJ];
static int        stub_nobj;
static int        stub_screen_ok = 1;   /* 置 0 可模拟"LVGL 未就绪" */
static lv_timer_t stub_timer_obj;
static lv_timer_t *stub_timer;

/* 屏幕尺寸。stub 默认 0 —— child_face.c 里 `s<=0` 会回落到 240，
 * 所以测试里要用 stub_screen_size() 显式设定，才能得到确定值。 */
static int stub_scr_w = 0;
static int stub_scr_h = 0;

/* 控件位置。child_face 用 align/set_pos/set_y 摆放元素，
