59	static void CHECK(int cond, const char *fmt, ...)
60	{
61	    va_list ap;
62	    va_start(ap, fmt);
63	    if (cond) {
64	        g_pass++;
65	        printf("    PASS  ");
66	    } else {
67	        g_fail++;
68	        printf("    FAIL  ");
69	    }
70	    vprintf(fmt, ap);
71	    va_end(ap);
